      "hsk": 1,
      "topic": "Gia đình & Bạn bè",
      "structure": "在家 (Ở nhà)",
      "vi": "Bố mẹ tôi hôm nay đều nghỉ ngơi ở nhà.",
      "zh": "我爸爸妈妈今天都在家休息。",
      "pinyin": "Wǒ bàba māma jīntiān dōu zài jiā xiūxi."
