      "topic": "Gia đình & Bạn bè",
      "structure": "爱 (Yêu thương)",
      "vi": "Tôi vô cùng yêu gia đình của tôi.",
      "zh": "我非常爱我的家。",
      "pinyin": "Wǒ fēicháng ài wǒ de jiā."
