      "hsk": 1,
      "topic": "Số đếm & Tuổi tác",
      "structure": "岁 (Tuổi)",
      "vi": "Bố tôi năm nay năm mươi tuổi rồi.",
      "zh": "我爸爸今年五十岁了。",
      "pinyin": "Wǒ bàba jīnnián wǔshí suì le."
