      "hsk": 3,
      "topic": "Du lịch & Hành lý",
      "structure": "风景 (Phong cảnh)",
      "vi": "Phong cảnh thiên nhiên ở vùng núi non này quả thực rất hùng vĩ và thơ mộng.",
      "zh": "这里的山水风景真的很美。",
      "pinyin": "Zhèlǐ de shānshuǐ fēngjǐng zhēn de hěn měi."
