      "hsk": 4,
      "topic": "Công sở & Tuyển dụng",
      "structure": "简历 (Sơ yếu lý lịch)",
      "vi": "Trước khi gửi sơ yếu lý lịch, bạn nên nhờ thầy cô hoặc bạn bè xem lại giúp.",
