      "topic": "Công sở & Tuyển dụng",
      "structure": "工资 / 待遇 (Lương bổng)",
      "vi": "Mức lương và chế độ đãi ngộ của công ty này rất hấp dẫn đối với các bạn sinh viên mới ra trường.",
      "zh": "这家公司的薪资待遇对刚毕业的大学生非常有吸引力。",
      "pinyin": "Zhè jiā gōngsī de xīnzī dàiyù duì gāng bìyè de dàxuéshēng fēicháng yǒu xīyǐnlì."
