      "topic": "Công sở & Tuyển dụng",
      "structure": "按时完成 (Hoàn thành đúng hạn)",
      "vi": "Chúng ta phải dốc toàn lực để hoàn thành bản thiết kế này đúng thời hạn đã cam kết.",
