      "hsk": 4,
      "topic": "Đàm phán & Thương mại",
      "structure": "信誉 (Uy tín)",
      "vi": "Đối với một doanh nghiệp, uy tín thương hiệu chính là tài sản quý giá nhất.",
      "zh": "对一家企业来说，良好的信誉是最宝贵的财富。",
      "pinyin": "Duì yì jiā qǐyè lái shuō, liánghǎo de xìnyù shì zuì bǎoguì de cáifù."
