      "vi": "Dự án mới này đã thu hút được nguồn vốn đầu tư khổng lồ từ các quỹ quốc tế.",
      "zh": "这个新项目吸引了大量来自海外的投资资金。",
      "pinyin": "Zhè gè xīn xiàngmù xīyǐn le dàliàng láizì hǎiwài de tóuzī zījīn."
