      "hsk": 4,
      "topic": "Đàm phán & Thương mại",
      "structure": "条款 (Điều khoản)",
      "vi": "Trước khi đặt bút ký tên, bạn phải đọc kỹ từng điều khoản ghi trong bản hợp đồng.",
