      "hsk": 4,
      "topic": "Tính cách & Tâm lý",
      "structure": "尊重 (Tôn trọng)",
      "vi": "Chúng ta phải luôn học cách tôn trọng thói quen và ý kiến khác biệt của người khác.",
      "zh": "我们要学会尊重别人的不同观点和生活习惯。",
      "pinyin": "Wǒmen yào xuéhuì zūnzhòng biérén de bùtóng guāndiǎn hé shēnghuó xíguàn."
