      "structure": "走上楼来 (Đi lên lầu)",
      "vi": "Tôi nghe thấy tiếng bước chân quen thuộc của bố đang từ từ bước lên tầng.",
      "zh": "我听见了爸爸走上楼来的脚步声。",
      "pinyin": "Wǒ tīngjiàn le bàba zǒu shàng lóu lái de jiǎobù shēng."
