      "structure": "由此可见 (Từ đó có thể thấy)",
      "vi": "Các số liệu thống kê đều tăng trưởng tốt, từ đó có thể thấy các chính sách kích cầu kinh tế đã phát huy tác dụng rõ rệt.",
      "zh": "多项核心经济指标明显向好，由此可见一系列扶持政策正在发挥积极显著的成效。",
