      "zh": "随着大众收入水平的普遍提升，随之而来的便是对高品质医疗康养服务的迫切需求。",
      "pinyin": "Suí zhe dàzhòng shōurù shuǐpíng de pǔbiàn tíshēng, suízhī'érlái de biàn shì duì gāo pǐnzhì yīliáo kāngyǎng fúwù de pòqiè xūqiú."
